import { useEffect, useState } from 'react';
import { useScrollReveal } from '../hooks/useScrollReveal';
import { useI18n, format } from '../i18n';
import { detectOS, detectArch, PLATFORMS, OS, Arch, Platform } from '../utils/detectOS';
import {
  buildDownloadUrl,
  fetchUpdateDownloads,
  findDownloadItem,
  formatFileSize,
  type UpdateDownloads,
} from '../lib/downloadApi';
import './Download.css';

