import { Fragment, useEffect, useMemo, useRef, useState, type ReactNode } from 'react';
import { Link } from 'react-router-dom';
import { useI18n, format } from '../i18n';
import {
  IMAP_PROVIDERS,
  matchesProvider,
  type ImapAuth,
  type ImapCategory,
} from '../lib/imapProviders';
import './ImapGuidePage.css';

const CATEGORIES: ImapCategory[] = ['global', 'china', 'enterprise'];

type AuthFilter =
  | 'all'
  | 'appPassword'
  | 'enableImap'
  | 'password'
  | 'oauth'
  | 'unsupported';

const AUTH_FILTERS: AuthFilter[] = [
  'all',
  'appPassword',
  'enableImap',
  'password',
  'unsupported',
];

/** 专用密码入口快捷卡片（顺序即展示顺序） */
const QUICK_PASSWORD_IDS = [
  'gmail',
  'icloud',
  'yahoo',
  'qqmail',
  'netease-163',
  'exmail',
  'feishu',
];

/** 微软官方说明：Outlook.com 需要 OAuth2，基本身份验证已停用 */
const MICROSOFT_OAUTH_DOC =
  'https://support.microsoft.com/outlook/pop-imap-and-smtp-settings-for-outlook-com#:~:text=Outlook.com%20%E9%9C%80%E8%A6%81%E4%BD%BF%E7%94%A8%E6%96%B0%E5%BC%8F%E8%BA%AB%E4%BB%BD%E9%AA%8C%E8%AF%81/OAuth2';

export default function ImapGuidePage() {
  const { t, locale, toggleLocale } = useI18n();
  const g = t.imapGuide;

  const [query, setQuery] = useState('');
  const [category, setCategory] = useState<ImapCategory | 'all'>('all');
  const [authFilter, setAuthFilter] = useState<AuthFilter>('all');
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [copied, setCopied] = useState<string | null>(null);
  const [openFaq, setOpenFaq] = useState<string[]>([]);

  const searchRef = useRef<HTMLInputElement>(null);

  const filtered = useMemo(
    () =>
      IMAP_PROVIDERS.filter((p) => {
        if (category !== 'all' && p.category !== category) return false;
        if (authFilter === 'appPassword' && p.auth !== 'appPassword') return false;
        if (authFilter === 'enableImap' && !p.enableImap) return false;
        if (authFilter === 'password' && p.auth !== 'password') return false;
        if (authFilter === 'oauth' && p.auth !== 'oauth') return false;
        if (authFilter === 'unsupported' && p.auth !== 'unsupported') return false;
        return matchesProvider(p, query);
      }),
    [query, category, authFilter],
  );

  const quickEntries = useMemo(
    () =>
      QUICK_PASSWORD_IDS.map((id) =>
        IMAP_PROVIDERS.find((p) => p.id === id),
      ).filter((p): p is NonNullable<typeof p> => !!p?.appPasswordUrl),
    [],
  );

  // 快捷键 "/" 聚焦搜索框
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement | null;
      const typing =
        target &&
        (target.tagName === 'INPUT' ||
          target.tagName === 'TEXTAREA' ||
          target.isContentEditable);
      if (e.key === '/' && !typing) {
        e.preventDefault();
        searchRef.current?.focus();
      }
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, []);

  const toggleFaq = (id: string) =>
    setOpenFaq((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id],
    );

  const copy = (text: string) => {
    navigator.clipboard
      ?.writeText(text)
      .then(() => {
        setCopied(text);
        window.setTimeout(() => setCopied(null), 1600);
      })
      .catch(() => {});
  };

  const jumpToTable = () => {
    const el = document.getElementById('table');
    if (!el) return;
    const sticky = document.querySelector<HTMLElement>('.imap__table-sticky');
    const stickyH =
      sticky && getComputedStyle(sticky).position === 'sticky'
        ? sticky.offsetHeight
        : 0;
    const top = el.getBoundingClientRect().top + window.scrollY - stickyH - 76;
    window.scrollTo({ top, behavior: 'smooth' });
  };

  const jumpToFaq = (id: string) => {
    setOpenFaq((prev) => (prev.includes(id) ? prev : [...prev, id]));
    window.requestAnimationFrame(() => {
      const el = document.getElementById(id);
      if (!el) return;
      const top = el.getBoundingClientRect().top + window.scrollY - 80;
      window.scrollTo({ top, behavior: 'smooth' });
    });
  };

  const authMeta = (auth: ImapAuth) => {
    if (auth === 'appPassword') {
      return { text: g.badgeAppPassword, cls: 'is-required' };
    }
    if (auth === 'password') {
      return { text: g.badgePassword, cls: 'is-password' };
    }
    if (auth === 'unsupported') {
      return { text: g.badgeUnsupported, cls: 'is-unsupported' };
    }
    return { text: g.badgeOauth, cls: 'is-oauth' };
  };

  const catLabel = (value: ImapCategory | 'all') => {
    if (value === 'all') return g.catAll;
    if (value === 'global') return g.catGlobal;
    if (value === 'china') return g.catChina;
    return g.catEnterprise;
  };

  const chipLabel = (value: AuthFilter) => {
    if (value === 'all') return g.chipAll;
    if (value === 'appPassword') return g.chipAppPassword;
    if (value === 'enableImap') return g.chipEnableImap;
    if (value === 'password') return g.chipPassword;
    if (value === 'unsupported') return g.chipUnsupported;
    return g.chipOauth;
  };

  /** 单个 Q/A 折叠项 */
  const faqItem = (id: string, question: string, answer: ReactNode) => {
    const open = openFaq.includes(id);
    return (
      <div
        key={id}
        className={`imap__faq-item ${open ? 'is-open' : ''}`}
        id={id}
      >
        <button
          type="button"
          className="imap__faq-q"
          aria-expanded={open}
          onClick={() => toggleFaq(id)}
        >
          <span className="imap__faq-mark" aria-hidden="true">
            {open ? '−' : '+'}
          </span>
          <span className="imap__faq-qtext">{question}</span>
          <svg
            className="imap__faq-chevron"
            width="16"
            height="16"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            aria-hidden="true"
          >
            <path d="m6 9 6 6 6-6" />
          </svg>
        </button>
        {open && <div className="imap__faq-a">{answer}</div>}
      </div>
    );
  };

  return (
    <div className="imap">
      <header className="imap__topbar">
        <div className="container imap__topbar-inner">
          <Link to="/" className="imap__back">
            <svg
              width="16"
              height="16"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="M19 12H5M12 19l-7-7 7-7" />
            </svg>
            {g.back}
          </Link>
          <span className="imap__topbar-title">Coco Toast / IMAP</span>
          <button
            type="button"
            className="imap__lang"
            onClick={toggleLocale}
            aria-label={t.language.switch}
            title={t.language.switch}
          >
            <svg
              width="15"
              height="15"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.8"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <circle cx="12" cy="12" r="10" />
              <path d="M2 12h20M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z" />
            </svg>
            <span>{locale === 'zh-CN' ? t.language.en : t.language.zh}</span>
          </button>
        </div>
      </header>

      <main className="imap__main">
        {/* ---------------------------------- Hero --------------------------------- */}
        <section className="container imap__hero">
          <p className="imap__badge">{g.badge}</p>
          <h1 className="imap__title">{g.title}</h1>
          <p className="imap__subtitle">{g.subtitle}</p>

          <ol className="imap__steps">
            {[
              { no: '01', title: g.step1, desc: g.step1Desc },
              { no: '02', title: g.step2, desc: g.step2Desc },
              { no: '03', title: g.step3, desc: g.step3Desc },
            ].map((s, i) => (
              <li className="imap__step" key={s.no}>
                <div className="imap__step-top">
                  <span className="imap__step-circle">{s.no}</span>
                  {i < 2 && <span className="imap__step-arrow" aria-hidden="true" />}
                </div>
                <span className="imap__step-title">{s.title}</span>
                <span className="imap__step-desc">{s.desc}</span>
              </li>
            ))}
          </ol>
        </section>

        {/* --------------------------------- Q / A --------------------------------- */}
        <section className="container imap__faq">
          {faqItem(
            'find',
            g.qFind,
            <>
              <p className="imap__pane-intro">{g.findIntro}</p>

              <div className="imap__method">
                <h3 className="imap__method-title">
                  <span className="imap__method-no">1</span>
                  {g.m1Title}
                </h3>
                <p className="imap__text">{g.m1Desc}</p>
                <code className="imap__kbd">{g.m1Keyword}</code>
                <p className="imap__text-muted">{g.m1Example}</p>
              </div>

              <div className="imap__method">
                <h3 className="imap__method-title">
                  <span className="imap__method-no">2</span>
                  {g.m2Title}
                </h3>
                <p className="imap__text">{g.m2Desc}</p>
                <code className="imap__kbd is-block">{g.m2Keywords}</code>
                <p className="imap__text-muted">{g.m2Note}</p>
              </div>

              <div className="imap__method">
                <h3 className="imap__method-title">
                  <span className="imap__method-no">3</span>
                  {g.m3Title}
                </h3>
                <p className="imap__text">{g.m3Desc}</p>
                <ul className="imap__rules">
                  {[g.m3Rule1, g.m3Rule2, g.m3Rule3].map((rule) => (
                    <li key={rule}>
                      <code>{rule}</code>
                    </li>
                  ))}
                </ul>
                <div className="imap__ports">
                  <span className="imap__ports-title">{g.m3PortTitle}</span>
                  <span className="imap__port is-primary">{g.m3PortSsl}</span>
                  <span className="imap__port">{g.m3PortStarttls}</span>
                  <span className="imap__port is-muted">{g.m3PortPlain}</span>
                </div>
                <p className="imap__text-muted">{g.m3UserNote}</p>
              </div>

              <div className="imap__method is-cta">
                <h3 className="imap__method-title">
                  <span className="imap__method-no">4</span>
                  {g.m4Title}
                </h3>
                <p className="imap__text">{g.m4Desc}</p>
                <button
                  type="button"
                  className="imap__link-btn"
                  onClick={jumpToTable}
                >
                  {g.m4Action} ↓
                </button>
              </div>
            </>,
          )}

          {faqItem(
            'password',
            g.qPassword,
            <>
              <p className="imap__pane-intro">{g.pwIntro}</p>

              <div className="imap__method">
                <h3 className="imap__method-title">{g.pwWhyTitle}</h3>
                <ul className="imap__list">
                  <li>{g.pwWhy1}</li>
                  <li>{g.pwWhy2}</li>
                  <li>{g.pwWhy3}</li>
                </ul>
              </div>

              <div className="imap__method">
                <h3 className="imap__method-title">{g.pwHowTitle}</h3>
                <ol className="imap__list is-ordered">
                  <li>{g.pwHow1}</li>
                  <li>{g.pwHow2}</li>
                  <li>{g.pwHow3}</li>
                  <li>{g.pwHow4}</li>
                </ol>
              </div>

              <div className="imap__method">
                <h3 className="imap__method-title">{g.pwQuickTitle}</h3>
                <div className="imap__quick">
                  {quickEntries.map((p) => (
                    <a
                      key={p.id}
                      className="imap__quick-item"
                      href={p.appPasswordUrl}
                      target="_blank"
                      rel="noreferrer"
                    >
                      <span className="imap__quick-name">{p.name}</span>
                      <span className="imap__quick-host">{p.host}</span>
                      <span className="imap__quick-go" aria-hidden="true">
                        →
                      </span>
                    </a>
                  ))}
                </div>
              </div>

              <div className="imap__callout">
                <h3 className="imap__method-title">{g.pwCautionTitle}</h3>
                <ul className="imap__list">
                  <li>{g.pwCaution1}</li>
                  <li>{g.pwCaution2}</li>
                  <li>{g.pwCaution3}</li>
                </ul>
              </div>
            </>,
          )}

          {faqItem(
            'basic-auth',
            g.qBasicAuth,
            <>
              <p className="imap__pane-intro">{g.basicAuthWhat}</p>
              <p className="imap__text">{g.basicAuthMs}</p>
              <p className="imap__text-muted">{g.basicAuthTip}</p>
              <a
                className="imap__link-btn"
                href={MICROSOFT_OAUTH_DOC}
                target="_blank"
                rel="noreferrer"
              >
                {g.basicAuthLink} ↗
              </a>
            </>,
          )}

          {faqItem(
            'troubleshoot',
            g.helpTitle,
            <>
              <ol className="imap__list is-ordered">
                <li>{g.help1}</li>
                <li>{g.help2}</li>
                <li>{g.help3}</li>
                <li>{g.help4}</li>
                <li>{g.help5}</li>
              </ol>
              <p className="imap__contact">
                {g.contact}
                <a href={`mailto:${t.proQuery.contactEmail}`}>
                  {t.proQuery.contactEmail}
                </a>
              </p>
            </>,
          )}
        </section>

        {/* ---------------------------------- 查询表 --------------------------------- */}
        <section className="container imap__table-section" id="table">
          <div className="imap__table-sticky">
            <header className="imap__table-head">
              <h2 className="imap__pane-title">{g.tableTitle}</h2>
              <p className="imap__pane-intro">{g.tableSubtitle}</p>
            </header>

            <div className="imap__toolbar">
              <div className="imap__search">
                <svg
                  width="15"
                  height="15"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                >
                  <circle cx="11" cy="11" r="7" />
                  <path d="m20 20-3.5-3.5" />
                </svg>
                <input
                  ref={searchRef}
                  type="search"
                  className="imap__search-input"
                  placeholder={g.searchPlaceholder}
                  value={query}
                  onChange={(e) => setQuery(e.target.value)}
                />
                <kbd className="imap__slash">/</kbd>
                {query && (
                  <button
                    type="button"
                    className="imap__search-clear"
                    onClick={() => setQuery('')}
                  >
                    {g.clear}
                  </button>
                )}
              </div>

              <label className="imap__select">
                <span className="imap__select-label">{g.filterCategory}</span>
                <select
                  value={category}
                  onChange={(e) =>
                    setCategory(e.target.value as ImapCategory | 'all')
                  }
                >
                  <option value="all">{g.catAll}</option>
                  {CATEGORIES.map((c) => (
                    <option key={c} value={c}>
                      {catLabel(c)}
                    </option>
                  ))}
                </select>
              </label>
            </div>
          </div>

          <div className="imap__chips">
            <span className="imap__chips-label">{g.filterAuth}</span>
            {AUTH_FILTERS.map((f) => (
              <button
                key={f}
                type="button"
                className={`imap__chip ${authFilter === f ? 'is-active' : ''}`}
                onClick={() => setAuthFilter(f)}
              >
                {chipLabel(f)}
              </button>
            ))}
            <span className="imap__count">
              {format(g.resultCount, { count: String(filtered.length) })}
            </span>
          </div>

          {filtered.length === 0 ? (
            <div className="imap__empty">
              <p className="imap__empty-title">{g.emptyTitle}</p>
              <p className="imap__empty-hint">{g.emptyHint}</p>
              <button
                type="button"
                className="imap__link-btn"
                onClick={() => jumpToFaq('find')}
              >
                {g.emptyAction} ↑
              </button>
            </div>
          ) : (
            <div className="imap__table-wrap">
              <table className="imap__table">
                <colgroup>
                  <col />
                  <col />
                  <col />
                  <col />
                  <col />
                  <col />
                </colgroup>
                <thead>
                  <tr>
                    <th>{g.colProvider}</th>
                    <th>{g.colHost}</th>
                    <th>{g.colPort}</th>
                    <th className="imap__col-sec">{g.colSecurity}</th>
                    <th>{g.colAuth}</th>
                    <th className="imap__col-docs">{g.colDocs}</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered.map((p) => {
                    const badge = authMeta(p.auth);
                    const open = expandedId === p.id;
                    const note = p.note
                      ? locale === 'zh-CN'
                        ? p.note.zh
                        : p.note.en
                      : null;
                    return (
                      <Fragment key={p.id}>
                        <tr
                          className={`imap__row ${open ? 'is-open' : ''}`}
                          onClick={() => setExpandedId(open ? null : p.id)}
                        >
                          <td className="imap__td-provider">
                            <div className="imap__provider-inner">
                              <span className="imap__provider-name">{p.name}</span>
                              <span className="imap__provider-tags">
                                {p.enableImap && (
                                  <span className="imap__mini-tag is-enable">
                                    {g.tagEnable}
                                  </span>
                                )}
                                {p.verify && (
                                  <span className="imap__mini-tag is-verify">
                                    {g.tagVerify}
                                  </span>
                                )}
                              </span>
                            </div>
                          </td>
                          <td className="imap__td-host">
                            {p.host ? (
                              <>
                                <code className="imap__host">{p.host}</code>
                                <button
                                  type="button"
                                  className="imap__copy"
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    copy(p.host.split(' 或 ')[0]);
                                  }}
                                >
                                  {copied === p.host.split(' 或 ')[0]
                                    ? g.copied
                                    : g.copy}
                                </button>
                              </>
                            ) : (
                              <span className="imap__host-empty">{g.noHost}</span>
                            )}
                          </td>
                          <td className="imap__td-port">
                            {p.port ? <code>{p.port}</code> : '—'}
                          </td>
                          <td className="imap__td-sec imap__col-sec">
                            {p.auth === 'oauth' || p.auth === 'unsupported'
                              ? '—'
                              : p.security.toUpperCase()}
                          </td>
                          <td className="imap__td-auth">
                            <span className={`imap__badge ${badge.cls}`}>
                              {badge.text}
                            </span>
                          </td>
                          <td className="imap__td-docs imap__col-docs">
                            {p.docsUrl ? (
                              <a
                                href={p.docsUrl}
                                target="_blank"
                                rel="noreferrer"
                                className="imap__docs-link"
                                onClick={(e) => e.stopPropagation()}
                              >
                                {g.open} ↗
                              </a>
                            ) : (
                              <span className="imap__docs-none">—</span>
                            )}
                          </td>
                        </tr>
                        {open && (
                          <tr className="imap__row-detail" key={`${p.id}-detail`}>
                            <td colSpan={6}>
                              <div className="imap__detail">
                                <p className="imap__detail-name">
                                  {p.name}
                                  <span className="imap__detail-alias">
                                    {p.aliases.split(' ').slice(0, 8).join(' · ')}
                                  </span>
                                </p>
                                {note && (
                                  <p className="imap__detail-note">
                                    <span className="imap__detail-label">
                                      {g.lblNote}
                                    </span>
                                    {note}
                                  </p>
                                )}
                                <div className="imap__detail-grid">
                                  <span className="imap__detail-label">
                                    {g.lblHost}
                                  </span>
                                  <span>
                                    {p.host ? (
                                      <code className="imap__host">
                                        {p.host}:{p.port}
                                      </code>
                                    ) : (
                                      <span className="imap__host-empty">
                                        {g.noHost}
                                      </span>
                                    )}
                                    {p.host && (
                                      <button
                                        type="button"
                                        className="imap__copy"
                                        onClick={() =>
                                          copy(p.host.split(' 或 ')[0])
                                        }
                                      >
                                        {copied === p.host.split(' 或 ')[0]
                                          ? g.copied
                                          : g.copy}
                                      </button>
                                    )}
                                  </span>
                                  {p.appPasswordUrl && (
                                    <>
                                      <span className="imap__detail-label">
                                        {g.lblAppPasswordUrl}
                                      </span>
                                      <a
                                        href={p.appPasswordUrl}
                                        target="_blank"
                                        rel="noreferrer"
                                      >
                                        {p.appPasswordUrl}
                                      </a>
                                    </>
                                  )}
                                  {p.docsUrl && (
                                    <>
                                      <span className="imap__detail-label">
                                        {g.lblDocsUrl}
                                      </span>
                                      <a
                                        href={p.docsUrl}
                                        target="_blank"
                                        rel="noreferrer"
                                      >
                                        {p.docsUrl}
                                      </a>
                                    </>
                                  )}
                                </div>
                              </div>
                            </td>
                          </tr>
                        )}
                      </Fragment>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}

          <p className="imap__table-note">{g.tableNote}</p>
          <p className="imap__disclaimer">{g.disclaimer}</p>
        </section>
      </main>
    </div>
  );
}
